    vestir: { slug: 'montres-habillees-automatiques', h1: 'Montres habillées automatiques', title: 'Montres habillées automatiques : épaisseur, taille et réserve comparées', description: 'Montres habillées automatiques classées par prix, avec épaisseur, diamètre et réserve de marche dans un même tableau.', criterio: 'montres de style habillé : boîtiers fins, cadrans épurés et bracelet cuir ou bracelet métal discret.' },
    campo: { slug: 'montres-de-terrain-automatiques', h1: 'Montres de terrain automatiques', title: 'Montres de terrain automatiques : les modèles et leurs valeurs', description: 'Montres de terrain automatiques, lisibles et robustes, avec calibre, étanchéité et dimensions comparés.', criterio: 'montres de style terrain : cadrans très lisibles, boîtiers simples et bracelets en tissu, cuir ou acier.' },
    deportivo: { slug: 'montres-sport-automatiques', h1: 'Montres sport automatiques', title: 'Montres sport automatiques, à bracelet intégré et GMT', description: 'Montres sport automatiques, modèles à bracelet intégré et GMT, avec calibre, réserve, verre et dimensions comparés.', criterio: 'montres de style sport : bracelets intégrés, GMT et designs pour tous les jours.' },
    piloto: { slug: 'montres-aviateur-automatiques', h1: 'Montres d’aviateur automatiques', title: 'Montres d’aviateur automatiques : cadrans type A et type B comparés', description: 'Montres d’aviateur automatiques allemandes et suisses, avec calibre, taille et verre dans un même tableau.', criterio: 'montres de style aviateur, avec des cadrans à lecture rapide conçus pour le cockpit.' },
    menos300: { slug: 'montres-automatiques-moins-de-300-euros', h1: 'Montres automatiques à moins de 300 €', title: 'Montres automatiques à moins de 300 € : les meilleures valeurs pour le prix', description: 'Les montres automatiques du catalogue dont la gamme de prix moyenne est inférieure à 300 €, comparées.', criterio: 'montres dont la gamme de prix moyenne est inférieure à 300 €.' },
    menos500: { slug: 'montres-automatiques-moins-de-500-euros', h1: 'Montres automatiques à moins de 500 €', title: 'Montres automatiques à moins de 500 € : comparatif en chiffres', description: 'Montres automatiques à moins de 500 €, avec calibre, réserve, verre et étanchéité dans un même tableau.', criterio: 'montres dont la gamme de prix moyenne est inférieure à 500 €.' },
    menos1000: { slug: 'montres-automatiques-moins-de-1000-euros', h1: 'Montres automatiques à moins de 1 000 €', title: 'Montres automatiques à moins de 1 000 € : suisses et japonaises comparées', description: 'Montres automatiques à moins de 1 000 €, de Seiko et Orient à Tissot et Hamilton, avec toutes leurs valeurs.', criterio: 'montres dont la gamme de prix moyenne est inférieure à 1 000 €.' },
    zafiro600: { slug: 'montres-automatiques-saphir-moins-de-600-euros', h1: 'Automatiques avec verre saphir à moins de 600 €', title: 'Montres automatiques avec verre saphir à moins de 600 €', description: 'Les montres automatiques avec verre saphir les moins chères du catalogue, avec leur calibre et leurs dimensions.', criterio: 'montres avec verre saphir et une gamme de prix moyenne inférieure à 600 €.' },
    zafiro: { slug: 'montres-automatiques-verre-saphir', h1: 'Montres automatiques avec verre saphir', title: 'Montres automatiques avec verre saphir : tous les modèles', description: 'Toutes les montres automatiques du catalogue avec verre saphir, classées par prix.', criterio: 'montres avec verre saphir, le plus résistant aux rayures.' },
    mm38: { slug: 'petites-montres-automatiques', h1: 'Montres automatiques de 39,5 mm ou moins', title: 'Petites montres automatiques : de 35 à 39,5 mm de diamètre', description: 'Montres automatiques jusqu’à 39,5 mm pour poignets fins, avec longueur corne à corne et épaisseur comparées.', criterio: 'montres jusqu’à 39,5 mm de diamètre, de la plus petite à la plus grande.' },
    mm40: { slug: 'montres-automatiques-40-mm', h1: 'Montres automatiques de 40 mm', title: 'Montres automatiques de 40 à 41 mm : la taille la plus polyvalente', description: 'Montres automatiques de 40 à 41 mm, la taille qui convient au plus grand nombre de poignets, comparées.', criterio: 'montres de 39,6 à 41 mm de diamètre.' },
    grandes: { slug: 'grandes-montres-automatiques', h1: 'Montres automatiques de 42 mm ou plus', title: 'Grandes montres automatiques : de 42 à 45 mm', description: 'Montres automatiques de 42 mm ou plus, avec leur longueur corne à corne pour savoir si elles vont à votre poignet.', criterio: 'montres de 42 mm de diamètre ou plus, de la plus petite à la plus grande.' },
    reserva70: { slug: 'montres-automatiques-80-heures-reserve-de-marche', h1: 'Automatiques avec 70 heures de réserve ou plus', title: 'Montres automatiques avec 70 ou 80 heures de réserve de marche', description: 'Montres automatiques qui tiennent un week-end à l’arrêt : 70 et 80 heures de réserve de marche.', criterio: 'montres avec 70 heures de réserve de marche ou plus, classées par réserve.' },
    wr200: { slug: 'montres-automatiques-200-metres', h1: 'Montres automatiques étanches à 200 mètres ou plus', title: 'Montres automatiques étanches à 200 ou 300 mètres', description: 'Montres automatiques étanches à 200 mètres ou plus, pour la plongée, comparées en chiffres.', criterio: 'montres étanches à 200 mètres ou plus.' },
    suizos: { slug: 'montres-automatiques-suisses', h1: 'Montres automatiques suisses', title: 'Montres automatiques suisses à moins de 1 500 €', description: 'Montres automatiques suisses de Tissot, Hamilton, Mido et Glycine, avec calibre et réserve de marche comparés.', criterio: 'montres de marques suisses.' },
    japoneses: { slug: 'montres-automatiques-japonaises', h1: 'Montres automatiques japonaises', title: 'Montres automatiques japonaises : Seiko, Orient et Citizen comparées', description: 'Montres automatiques japonaises de Seiko, Orient et Citizen, avec leurs calibres maison et toutes leurs valeurs.', criterio: 'montres de marques japonaises.' },
